function t(k){return (EXTRA_I18N[lang]&&EXTRA_I18N[lang][k])||I18N[lang][k]||ULTIMATE_EN[k]||EXTRA_I18N.en?.[k]||I18N.en[k]||k}
function dayKey(d){return d.toISOString().slice(0,10)}
function utcDayOffset(n){let d=new Date();d.setUTCHours(0,0,0,0);d.setUTCDate(d.getUTCDate()+n);return dayKey(d)}
function localDateKey(iso,tz){try{const parts=new Intl.DateTimeFormat("en-CA",{timeZone:tz,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date(iso));const o=Object.fromEntries(parts.map(x=>[x.type,x.value]));return `${o.year}-${o.month}-${o.day}`}catch(_){return iso.slice(0,10)}}
function formatZone(iso,tz,withZone=true){try{return new Intl.DateTimeFormat("en-GB",{timeZone:tz,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hour12:false,timeZoneName:withZone?"short":undefined}).format(new Date(iso))}catch(_){return iso}}
function zoneList(){try{return Intl.supportedValuesOf("timeZone")}catch(_){return ["UTC","Europe/Belgrade","Europe/London","Europe/Paris","America/New_York","America/Chicago","America/Denver","America/Los_Angeles","Asia/Jerusalem","Asia/Tokyo","Australia/Sydney","Pacific/Auckland"]}}
function zoneLabel(z){if(z==="UTC")return "UTC";return z.replaceAll("_"," ")}
function flag(c){return `<img class="flag" src="/flags/${LANGUAGES[c].flag}.svg" alt="" loading="lazy">`}

function setDirection(){document.documentElement.dir=lang==="he"?"rtl":"ltr";document.documentElement.lang=lang}
function selectLanguage(c){lang=c;STORE.set("ncaaLang",lang);setDirection();renderLanguagePicker();render()}
function renderLanguagePicker(){const box=$("lang");if(!box)return;const current=LANGUAGES[lang];box.innerHTML=`<button class="lang-current" type="button" aria-expanded="false">${flag(lang)}<span>${current.name}</span><span class="lang-arrow">▾</span></button><div class="lang-menu">${Object.entries(LANGUAGES).map(([c,i])=>`<button class="lang-option ${c===lang?"selected":""}" type="button" data-lang="${c}">${flag(c)}<span>${i.name}</span></button>`).join("")}</div>`;const btn=box.querySelector(".lang-current");btn.onclick=()=>{box.classList.toggle("open");btn.setAttribute("aria-expanded",box.classList.contains("open"))};box.querySelectorAll(".lang-option").forEach(b=>b.onclick=()=>{selectLanguage(b.dataset.lang);box.classList.remove("open")});document.addEventListener("click",e=>{if(!box.contains(e.target))box.classList.remove("open")})}
function renderTimezonePicker(){
  const box=$("tz"); if(!box)return;
  const zones=zoneList(); if(!zones.includes("UTC"))zones.unshift("UTC");
  if(!zones.includes(timezone))timezone="UTC";
  box.innerHTML=`<div class="tz-search-wrap">
    <button type="button" class="tz-current" id="tzCurrent" aria-expanded="false"><span>◷</span><strong>${esc(zoneLabel(timezone))}</strong><span class="tz-chevron">⌄</span></button>
    <div class="tz-menu" id="tzMenu">
      <div class="tz-menu-head"><b>${esc(t("timezone"))}</b><small>UTC is default • choose only when needed</small></div>
      <input id="tzSearch" class="tz-search" type="search" autocomplete="off" placeholder="Search time zone…" aria-label="Search time zone">
      <div id="tzResults" class="tz-results"></div>
    </div>
  </div>`;
  const current=$("tzCurrent"), menu=$("tzMenu"), input=$("tzSearch"), results=$("tzResults");
  const paint=(q="")=>{
    const query=q.trim().toLowerCase();
    let matches=zones.filter(z=>!query || z.toLowerCase().replaceAll("_"," ").includes(query));
    if(!query) matches=[timezone, ...zones.filter(z=>z!==timezone)].slice(0,8);
    else matches=matches.slice(0,10);
    results.innerHTML=matches.length?matches.map(z=>`<button type="button" class="tz-option ${z===timezone?"selected":""}" data-zone="${esc(z)}"><span>${z==="UTC"?"🌐":"◉"}</span><strong>${esc(zoneLabel(z))}</strong>${z===timezone?"<b>✓</b>":""}</button>`).join(""):`<div class="tz-no-results">No matching time zones.</div>`;
    results.querySelectorAll(".tz-option").forEach(btn=>btn.onclick=()=>{
      timezone=btn.dataset.zone||"UTC"; STORE.set("ncaaTimezone",timezone); closeTimezoneMenus(); render(); clock();
    });
  };
  current.onclick=()=>{const open=box.classList.toggle("open");current.setAttribute("aria-expanded",String(open));if(open){input.value="";paint();setTimeout(()=>input.focus(),0)}};
  input.oninput=e=>paint(e.target.value);
  paint();
  if(!window.__ncaaTimezoneOutside){
    document.addEventListener("click",e=>{if(!e.target.closest(".timezone-picker,.side-timezone-search"))closeTimezoneMenus()});
    window.__ncaaTimezoneOutside=true;
  }
}
function closeTimezoneMenus(){document.querySelectorAll(".timezone-picker.open").forEach(x=>x.classList.remove("open"));document.querySelectorAll(".side-timezone-search.open").forEach(x=>x.classList.remove("open"));}
function renderSideTimezone(){
  const box=$("tzSide"); if(!box)return;
  box.innerHTML=`<div class="zone-current"><span>Selected zone</span><strong>${esc(zoneLabel(timezone))}</strong></div><button type="button" class="side-zone-change" id="sideZoneChange">⌕ Search / change time zone</button><div class="zone-note">Event times stay in UTC until you explicitly choose another zone.</div>`;
  $("sideZoneChange").onclick=()=>{const top=$("tzCurrent");if(top){top.click();setTimeout(()=>$("tzSearch")?.focus(),0)}};
}
function zoneTime(iso){return formatZone(iso,timezone,true)}
function zoneHM(iso,tz=timezone){try{return new Intl.DateTimeFormat("en-GB",{timeZone:tz,hour:"2-digit",minute:"2-digit",hour12:false}).format(new Date(iso))}catch(_){return iso.slice(11,16)}}
function officialSearchButton(team,kind){if(!team||team==="TBD")return"";const q=kind==="schedule"?`${team} official athletics schedule`:`${team} official athletics`;const u=`https://www.google.com/search?q=${encodeURIComponent(q)}`;return linkButton(u,kind==="schedule"?t("search_schedule"):t("search_official"))}
function sportIcon(k){return ({football:"🏈",basketball:"🏀",soccer:"⚽",baseball:"⚾",volleyball:"🏐",softball:"🥎",ice_hockey:"🏒",field_hockey:"🏑",lacrosse:"🥍",wrestling:"🤼",gymnastics:"🤸",track_field:"🏃",swimming_diving:"🏊",cross_country:"🏃‍♂️",water_polo:"🤽",rowing:"🚣",golf:"⛳",fencing:"🤺",bowling:"🎳",rifle:"🎯",skiing:"⛷️",beach_volleyball:"🏐"}[k]||"◈")}
function renderSportStrip(){
  const counts={};events.forEach(e=>{const k=canonicalSport(e.sport);if(k!=="tennis")counts[k]=(counts[k]||0)+1});
  const keys=Object.keys(SPORTS).filter(k=>k!=="tennis");
  const selected=$('sport').value||"";
  $('sportStrip').innerHTML=`<button class="sport-tile ${selected===""?"active":""}" data-sp=""><b>▦</b><strong>All Sports</strong><small>${events.length}</small></button>`+
    keys.map(k=>`<button class="sport-tile ${selected===k?"active":""}" data-sp="${k}" title="Show ${esc(SPORTS[k])} games for the next 7 days"><b>${sportIcon(k)}</b><strong>${esc(SPORTS[k])}</strong><small>${counts[k]||0} ${counts[k]===1?"game":"games"}</small></button>`).join("");
  document.querySelectorAll(".sport-tile").forEach(b=>b.onclick=()=>{
    document.querySelectorAll(".sport-tile").forEach(x=>x.classList.remove("active"));b.classList.add("active");
    $('sport').value=b.dataset.sp;
    range="next";
    document.querySelectorAll("#ranges button").forEach(x=>x.classList.toggle("active",x.dataset.r==="next"));
    render();
    window.scrollTo({top:document.querySelector('.dashboard')?.offsetTop||0,behavior:'smooth'});
  });
}
function renderFeatured(){const f=events.filter(e=>e.start_utc).slice().sort((a,b)=>new Date(a.start_utc)-new Date(b.start_utc))[0];if(!f){$("featured").innerHTML=`<div class="panel-title">★ &nbsp;Featured Match</div><div class="empty">No verified event.</div>`;return}const hs=f.home_score??"—",as=f.away_score??"—";$("featured").innerHTML=`<div class="panel-title">★ &nbsp;Featured Match <span class="live-dot">● LIVE</span></div><div class="featured-card"><div class="feature-sport">${sportIcon(f.sport)} ${esc(SPORTS[f.sport]||f.sport)}</div><div class="featured-match"><div><div class="feature-logo">${f.away_logo?`<img src="${esc(f.away_logo)}" alt="" loading="lazy">`:""}</div><b>${esc(f.away||"TBD")}</b></div><div class="feature-score">${hs} <span>:</span> ${as}</div><div><div class="feature-logo">${f.home_logo?`<img src="${esc(f.home_logo)}" alt="" loading="lazy">`:""}</div><b>${esc(f.home||"TBD")}</b></div></div><small>${esc(zoneTime(f.start_utc))} • ${esc(f.venue||"NCAA")}</small><button class="feature-btn">Open Game Center →</button></div>`;$("featured").querySelector(".feature-btn").onclick=()=>detail(f)}
function updateDashboardMeta(list){const title=range==="today"?"DANAS":range==="yesterday"?"JUČE":range==="tomorrow"?"SUTRA":"SLEDEĆIH 7 DANA";$("feedTitle").textContent=title;$("feedMeta").textContent=`${new Date().toISOString().slice(0,10)} • ${list.length} ${t("events")} • ${zoneLabel(timezone)}`}
function closeGameCenter(){$("modal").classList.add("hidden");document.body.classList.remove("modal-open");}
function openCommandPalette(initial=""){
  const box=$("commandPalette"); if(!box)return;
  box.classList.remove("hidden");
  const input=$("commandInput");
  input.value=initial||"";
  paintCommandSuggestions(input.value);
  setTimeout(()=>input.focus(),0);
}
function closeCommandPalette(){ $("commandPalette")?.classList.add("hidden"); }
function paintCommandSuggestions(query=""){
  const host=$("commandSuggestions"); if(!host)return;
  const q=String(query||"").trim().toLowerCase();
  const out=[];
  const push=(type,label,sub,action,logo="",icon="◈")=>{
    if(q && !(label+" "+sub).toLowerCase().includes(q))return;
    out.push({type,label,sub,action,logo,icon});
  };
  const schoolMap=new Map();
  for(const arr of Object.values(directory.sports||{})) for(const x of (arr||[])){ if(x?.name) schoolMap.set(String(x.name).toLowerCase(),x); }
  for(const [k,x] of [...schoolMap.entries()].slice(0,80)) push("School",x.name,`${schoolItemSports(x.name).map(s=>SPORTS[s]||s).slice(0,3).join(" • ")||"NCAA team"}`,()=>openSchoolPage(x),x.logo,"⌂");
  for(const [k,v] of Object.entries(SPORTS).filter(([k])=>k!=="tennis")) push("Sport",v,"Open sport schedule",()=>{closeCommandPalette();$("sport").value=k;renderSportStrip();render() },"",sportIcon(k));
  for(const c of Object.keys(directory.conferences||{}).sort().slice(0,60)) push("Conference",c,"Open conference filter",()=>{closeCommandPalette();$("conference").value=c;render() },"","♟");
  for(const e of events.slice().sort((a,b)=>new Date(a.start_utc)-new Date(b.start_utc)).slice(0,80)){
    const label=`${e.away||"TBD"} vs ${e.home||"TBD"}`;
    push("Game",label,`${SPORTS[e.sport]||e.sport}${e.conference?" • "+e.conference:""}`,()=>{closeCommandPalette();detail(e)},e.away_logo||e.home_logo,sportIcon(e.sport));
  }
  const dedupe=new Set();
  const filtered=out.filter(x=>{const k=x.type+"|"+x.label;if(dedupe.has(k))return false;dedupe.add(k);return true}).slice(0,q?12:8);
  host.innerHTML=filtered.length?filtered.map((x,i)=>`<button class="suggestion" type="button" data-suggestion-index="${i}"><span class="suggestion-icon">${x.logo?`<img class="suggestion-logo" src="${esc(x.logo)}" alt="" loading="lazy">`:x.icon}</span><span class="suggestion-main"><strong>${esc(x.label)}</strong><small>${esc(x.sub)}</small></span><span class="suggestion-type">${esc(x.type)}</span></button>`).join(""): `<div class="command-empty">No matching NCAA results yet.</div>`;
  host.querySelectorAll(".suggestion").forEach((b,i)=>b.onclick=filtered[i].action);
}
function openHub(kind){
  const modal=$("hubModal"), title=$("hubTitle"), body=$("hubBody"); if(!modal||!title||!body)return;
  const esc2=esc;
  if(kind==="standings"){
    title.textContent="NCAA STANDINGS & RANKINGS";
    const sports=Object.entries(SPORTS).filter(([k])=>k!=="tennis").map(([k,v])=>`<button type="button" class="hub-link" data-sport="${k}"><span>${sportIcon(k)}</span><b>${esc2(v)}</b><small>Open schedule & team directory →</small></button>`).join("");
    body.innerHTML=`<p class="hub-intro">Use the official provider links below for current standings and rankings. Our schedule database remains the source for verified events.</p><div class="hub-grid">${sports}</div><div class="hub-footer-links"><a class="detail-link" href="https://www.ncaa.com/standings" target="_blank" rel="noopener">NCAA Standings ↗</a><a class="detail-link" href="https://www.espn.com/college-sports/standings" target="_blank" rel="noopener">ESPN Standings ↗</a></div>`;
    body.querySelectorAll(".hub-link").forEach(b=>b.onclick=()=>{closeHub();$("sport").value=b.dataset.sport;range="next";document.querySelectorAll("#ranges button").forEach(x=>x.classList.toggle("active",x.dataset.r==="next"));render();$("schedule").scrollIntoView({behavior:"smooth",block:"start"});});
  }else{
    title.textContent="NCAA NEWS";
    body.innerHTML=`<div class="news-hub"><a class="news-hub-card" href="https://www.ncaa.com/news" target="_blank" rel="noopener"><b>NCAA News</b><span>Official NCAA news and updates ↗</span></a><a class="news-hub-card" href="https://www.espn.com/college-sports/" target="_blank" rel="noopener"><b>ESPN College Sports</b><span>Scores, stories and updates ↗</span></a><a class="news-hub-card" href="https://www.ncaa.com/sports" target="_blank" rel="noopener"><b>NCAA Sports</b><span>Explore all NCAA sports ↗</span></a></div>`;
  }
  modal.classList.remove("hidden"); document.body.classList.add("modal-open");
}
function closeHub(){const m=$("hubModal");if(m)m.classList.add("hidden");document.body.classList.remove("modal-open");}
function setup(){
  renderLanguagePicker();renderTimezonePicker();renderSideTimezone();
  $("ranges").innerHTML=[["yesterday","yesterday"],["today","today"],["tomorrow","tomorrow"],["next","next"]].map(([k,v])=>`<button data-r="${v}">${t(k)}</button>`).join("");
  document.querySelectorAll("#ranges button").forEach(b=>b.onclick=()=>{range=b.dataset.r;document.querySelectorAll("#ranges button").forEach(x=>x.classList.toggle("active",x===b));render()});
  $("search").oninput=render;$("schoolSearch").oninput=e=>{schoolQuery=e.target.value||"";renderSchoolDirectory()};
  $("timeFrom").onchange=e=>{timeFrom=e.target.value;render()};$("timeTo").onchange=e=>{timeTo=e.target.value;render()};
  $("clearFilters").onclick=()=>{timeFrom="";timeTo="";$("timeFrom").value="";$("timeTo").value="";$("search").value="";$("sport").value="";$("conference").value="";renderSportStrip();render()};
  $("sport").onchange=()=>{document.querySelectorAll(".sport-tile").forEach(x=>x.classList.toggle("active",x.dataset.sp===$("sport").value));render()};
  $("conference").onchange=render;
  $("sort").onchange=render;
  $("globalSearchBtn")?.addEventListener("click",()=>openCommandPalette());
  $("commandClose")?.addEventListener("click",closeCommandPalette);
  $("commandPalette")?.addEventListener("click",e=>{if(e.target.id==="commandPalette")closeCommandPalette()});
  $("commandInput")?.addEventListener("input",e=>paintCommandSuggestions(e.target.value));
  document.querySelectorAll(".utility-action").forEach(b=>b.onclick=()=>{
    const a=b.dataset.action;
    if(a==="schedule"){$("schedule").scrollIntoView({behavior:"smooth",block:"start"});}
    else if(a==="live"){
      const live=events.filter(e=>String(e.status||"").toLowerCase().includes("live"));
      if(live[0])detail(live[0]); else {openCommandPalette("live");}
    } else if(a==="game") openCommandPalette();
    else if(a==="news") window.open("https://www.ncaa.com/news","_blank","noopener");
  });
  $("close").onclick=()=>closeGameCenter();
  $("hubClose")?.addEventListener("click",closeHub); $("hubModal")?.addEventListener("click",e=>{if(e.target.id==="hubModal")closeHub()});
  $("modal").addEventListener("click",e=>{if(e.target.id==="modal")closeGameCenter()});
  document.addEventListener("keydown",e=>{
    if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();openCommandPalette()}
    if(e.key==="Escape"){
      if(!$('commandPalette').classList.contains('hidden')) closeCommandPalette();
      else if(!$('hubModal')?.classList.contains('hidden')) closeHub();
      else if(!$('modal').classList.contains('hidden')) closeGameCenter();
    }
  });
  document.querySelectorAll(".nav-item").forEach(b=>b.onclick=()=>{
    document.querySelectorAll(".nav-item").forEach(x=>x.classList.remove("active")); b.classList.add("active");
    const id=b.dataset.jump;
    if(id==="home") $("home").scrollIntoView({behavior:"smooth",block:"start"});
    else if(id==="schedule") { range="today"; document.querySelectorAll("#ranges button").forEach(x=>x.classList.toggle("active",x.dataset.r==="today")); $("schedule").scrollIntoView({behavior:"smooth",block:"start"}); render(); }
    else if(id==="teams") { $("schoolList")?.scrollIntoView({behavior:"smooth",block:"center"}); $("schoolSearch")?.focus(); }
    else if(id==="conferences") { $("conference")?.scrollIntoView({behavior:"smooth",block:"center"}); $("conference")?.focus(); }
    else if(id==="standings") openHub("standings");
    else if(id==="news") openHub("news");
    else if(id==="settings") $("settings").scrollIntoView({behavior:"smooth",block:"center"});
  });
}

function applyTexts(){
  renderTimezonePicker();renderSideTimezone();$("sub").textContent=t("sub");$("search").placeholder=t("search");$("ranges").querySelectorAll("button").forEach(b=>b.textContent=t(b.dataset.r==="next"?"next":b.dataset.r));
  const s=$("sport").value,c=$("conference")?.value||"";
  $("sport").innerHTML=`<option value="">${t("all")}</option>`+Object.entries(SPORTS).filter(([k])=>k!=="tennis").map(([k,v])=>`<option value="${k}">${v}</option>`).join("");$("sport").value=s;
  const confs=[...new Set([...NCAA_CONFERENCES,...Object.keys(directory.conferences||{})])].sort();$("conference").innerHTML=`<option value="">All Conferences</option>`+confs.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join("");$("conference").value=c;
}
function schoolSearchUrl(team){
  if(!team||team==='TBD') return '#';
  return `https://www.google.com/search?q=${encodeURIComponent(team+' official athletics')}`;
}
function providerMark(source){
  const s=String(source||'').trim();
  if(!s) return '';
  const key=s.toLowerCase();
  const mark=key.includes('espn')?'ESPN':key.includes('ncaa')?'NCAA':key.includes('official')?'OFFICIAL':s.split(/\s+/)[0].slice(0,10).toUpperCase();
  return `<span class="source-badge"><span class="source-mark">${esc(mark)}</span><span>${esc(s)}</span></span>`;
}
function schoolItemSports(name){
  const out=[];
  for(const [sport,arr] of Object.entries(directory.sports||{})){
    if((arr||[]).some(x=>String(x.name||"").toLowerCase()===String(name||"").toLowerCase())) out.push(sport);
  }
  return out;
}
function openSchoolPage(team){
  const name=team?.name||team; if(!name||name==='TBD')return;
  const sports=schoolItemSports(name);
  const schoolEvents=events.filter(e=>String(e.home||"").toLowerCase()===name.toLowerCase()||String(e.away||"").toLowerCase()===name.toLowerCase());
  const logo=team?.logo||schoolEvents.find(e=>String(e.home||"").toLowerCase()===name.toLowerCase())?.home_logo||schoolEvents.find(e=>String(e.away||"").toLowerCase()===name.toLowerCase())?.away_logo||"";
  const url=team?.url||schoolSearchUrl(name);
  const d=$("detail");
  d.innerHTML=`<div class="school-page">
    <div class="school-hero"><div class="school-hero-logo">${logo?`<img src="${esc(logo)}" alt="${esc(name)}">`:`<span>${esc(name.slice(0,1))}</span>`}</div><div><div class="eyebrow">SCHOOL PROFILE</div><h2>${esc(name)}</h2><p>All available NCAA sports, teams, schedules and related information for this school.</p></div></div>
    <div class="school-page-actions"><a class="detail-link primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Official / provider school page ↗</a><a class="detail-link" href="${esc(schoolSearchUrl(name))}" target="_blank" rel="noopener noreferrer">Find official athletics ↗</a></div>
    <div class="school-sport-tabs"><button class="school-sport-tab active" data-school-sport="">All Sports</button>${sports.map(k=>`<button class="school-sport-tab" data-school-sport="${esc(k)}">${esc(SPORTS[k]||k)}</button>`).join("")}</div>
    <div class="school-page-grid"><section><div class="gc-section"><h3>Sports covered by this school</h3><div class="school-sport-grid">${(sports.length?sports:Object.keys(SPORTS).filter(k=>schoolEvents.some(e=>e.sport===k))).map(k=>`<button class="school-sport-card" data-school-sport="${esc(k)}"><span>${sportIcon(k)}</span><strong>${esc(SPORTS[k]||k)}</strong></button>`).join("")||`<div class="empty">No verified sport coverage is currently loaded.</div>`}</div></div>
    <div class="gc-section"><h3>Schedule & results</h3><div id="schoolEventList" class="school-event-list"></div></div></section>
    <aside class="school-side-card"><h3>School information</h3><div><span>Sports</span><b>${sports.length}</b></div><div><span>Loaded events</span><b>${schoolEvents.length}</b></div><div><span>Conference</span><b>${esc(team?.conference||schoolEvents.find(e=>String(e.home||"").toLowerCase()===name.toLowerCase()||String(e.away||"").toLowerCase()===name.toLowerCase())?.conference||"—")}</b></div><div><span>Logo</span><b>${logo?"Available":"Not verified"}</b></div></aside></div>
  </div>`;
  $("modal").classList.remove("hidden");document.body.classList.add("modal-open");
  const renderSchoolEvents=(sport="")=>{
    const arr=schoolEvents.filter(e=>!sport||e.sport===sport).sort((a,b)=>new Date(a.start_utc)-new Date(b.start_utc)).slice(0,100);
    $("schoolEventList").innerHTML=arr.length?arr.map(e=>{const isHome=String(e.home||"").toLowerCase()===name.toLowerCase();return `<button class="school-event-row" data-event-id="${esc(e.id)}"><span class="school-event-date">${esc(zoneTime(e.start_utc))}</span><span>${esc(e.away||"TBD")}</span><b>${esc(e.away_score??"—")} : ${esc(e.home_score??"—")}</b><span>${esc(e.home||"TBD")}</span><em>${esc(SPORTS[e.sport]||e.sport)} • ${isHome?"HOME":"AWAY"}</em></button>`}).join(""):`<div class="empty">No verified events loaded for this sport.</div>`;
    $("schoolEventList").querySelectorAll(".school-event-row").forEach(btn=>btn.onclick=()=>{const ev=events.find(e=>e.id===btn.dataset.eventId);if(ev)detail(ev)});
  };
  document.querySelectorAll(".school-sport-tab,.school-sport-card").forEach(btn=>btn.onclick=()=>{const sp=btn.dataset.schoolSport||"";document.querySelectorAll(".school-sport-tab").forEach(x=>x.classList.toggle("active",x.dataset.schoolSport===sp));renderSchoolEvents(sp)});
  renderSchoolEvents("");
}
function renderSchoolDirectory(){
  const sp=$("sport").value||""; const conf=$("conference")?.value||"";
  let teams=[];
  if(conf && directory.conferences?.[conf]) teams=directory.conferences[conf];
  else if(sp && directory.sports?.[sp]) teams=directory.sports[sp];
  else { const map=new Map(); Object.values(directory.sports||{}).flat().forEach(x=>map.set(x.name,x)); teams=[...map.values()].sort((a,b)=>a.name.localeCompare(b.name)); }
  const q=schoolQuery.trim().toLowerCase(); if(q) teams=teams.filter(x=>String(x.name||"").toLowerCase().includes(q));
  $("schoolCount").textContent=teams.length;
  $("schoolList").innerHTML=teams.length ? teams.map(x=>`<button type="button" class="school-chip" data-school-name="${esc(x.name)}"><span class="school-chip-logo">${x.logo?`<img src="${esc(x.logo)}" alt="" loading="lazy">`:`<span>${esc((x.name||"N").slice(0,1))}</span>`}</span><span>${esc(x.name)}</span><b>›</b></button>`).join("") : `<div class="empty mini-empty">No verified schools match this selection.</div>`;
  $("schoolList").querySelectorAll(".school-chip").forEach(btn=>{const team=teams.find(x=>x.name===btn.dataset.schoolName);btn.onclick=()=>openSchoolPage(team)});
}
async function loadDirectory(){
  try{const r=await fetch("/api/directory",{cache:"no-store"});if(r.ok)directory=await r.json();}
  catch(e){console.warn("directory",e)}
  renderSchoolDirectory();
}
function render(){
  applyTexts();
  const todayKey=localDateKey(new Date().toISOString(),timezone);
  const base=new Date(todayKey+'T00:00:00Z');
  const offset=range==='yesterday'?-1:range==='tomorrow'?1:0;
  let days=[];
  if(range==='next'){
    for(let i=1;i<=7;i++){const d=new Date(base);d.setUTCDate(d.getUTCDate()+i);days.push(dayKey(d))}
  }else{
    const d=new Date(base);d.setUTCDate(d.getUTCDate()+offset);days=[dayKey(d)]
  }
  const q=($('search').value||'').toLowerCase(),sp=$('sport').value,conf=$("conference")?.value||"";
  let list=events.filter(e=>{
    if(!e.start_utc||!days.includes(localDateKey(e.start_utc,timezone)))return false;
    if(sp&&e.sport!==sp)return false;
    if(conf&&String(e.conference||"")!==conf)return false;
    const hm=zoneHM(e.start_utc);
    if(timeFrom&&hm<timeFrom)return false;
    if(timeTo&&hm>timeTo)return false;
    return JSON.stringify(e).toLowerCase().includes(q)
  });
  if($('sort')?.value==='Start Time (Latest)'||$('sort')?.value==='Najkasnije prvo') list.sort((a,b)=>new Date(b.start_utc)-new Date(a.start_utc));
  else list.sort((a,b)=>new Date(a.start_utc)-new Date(b.start_utc));
  $('feed').innerHTML='';
  updateDashboardMeta(list);renderSportStrip();renderFeatured();renderSchoolDirectory();
  if(!list.length){$('feed').innerHTML=`<div class="empty">${t('empty')}</div>`;return}
  for(const day of days){
    const arr=list.filter(e=>localDateKey(e.start_utc,timezone)===day);
    if(!arr.length)continue;
    const h=document.createElement('div');h.className='day';h.textContent=`${day} • ${arr.length} ${t('events')} • ${zoneLabel(timezone)}`;$('feed').appendChild(h);
    arr.forEach(e=>{
      const card=document.createElement('article');card.className='event';card.style.setProperty('--event-color',e.color||'#1597ff');
      const hasScore=(e.home_score??'')!==''||(e.away_score??'');
      const score=hasScore?`<span class="mini-score">${esc(e.away_score??'—')} : ${esc(e.home_score??'—')}</span>`:`<span class="mini-score">—</span>`;
      const local=zoneTime(e.start_utc);
      const logo=(url,name,side)=>url?`<a class="team-logo-link feed-logo-link" href="${esc(schoolSearchUrl(name))}" target="_blank" rel="noopener noreferrer" title="Open ${esc(name||'team')} official search" onclick="event.stopPropagation()"><img class="event-team-logo" src="${esc(url)}" alt="${esc(name||'')}" loading="lazy" onerror="this.style.display='none'"></a>`:`<a class="team-logo-link feed-logo-link placeholder" href="${esc(schoolSearchUrl(name))}" target="_blank" rel="noopener noreferrer" title="Open ${esc(name||'team')} official search" onclick="event.stopPropagation()">${side}</a>`;
      card.innerHTML=`
        <div class="time"><strong>${esc(local.slice(12,17))}</strong><small>${esc(zoneLabel(timezone))}</small><div class="utc-mini">${esc(e.start_utc.slice(11,16))} UTC</div></div>
        <div class="matchup">
          <div class="team-line">
            <span class="team-side away-side">${logo(e.away_logo,e.away,'A')}<b>${esc(e.away||'TBD')}</b></span>
            <span class="vs-block"><span class="vs">VS</span>${score}<button class="game-center-btn" type="button">${t('details')} →</button></span>
            <span class="team-side home-side"><b>${esc(e.home||'TBD')}</b>${logo(e.home_logo,e.home,'H')}</span>
          </div>
          <div class="meta">${esc(SPORTS[e.sport]||e.sport)}${e.conference?' • '+esc(e.conference):''} • ${esc(e.status||t('scheduled'))}</div>
        </div>`;
      card.onclick=()=>detail(e);card.querySelector('.game-center-btn').onclick=(ev)=>{ev.stopPropagation();detail(e)};$('feed').appendChild(card)
    })
  }
}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]))}
function linkButton(url,label){if(!url)return"";return `<a class="detail-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`}
function simpleValue(v){if(v==null)return"";if(typeof v==="string"||typeof v==="number"||typeof v==="boolean")return esc(v);if(Array.isArray(v))return v.map(simpleValue).join(" • ");if(typeof v==="object")return Object.entries(v).filter(([k,x])=>x!=null&&x!=="").slice(0,12).map(([k,x])=>`<div><b>${esc(k)}:</b> ${simpleValue(x)}</div>`).join("");return""}
function section(title,body){return body?`<section class="gc-section"><h3>${title}</h3>${body}</section>`:""}
function renderPlays(plays){if(!Array.isArray(plays)||!plays.length)return`<div class="muted">${t("no_data")}</div>`;return `<div class="play-count">${plays.length} records • ${t("refresh")}</div><div class="plays">${plays.slice().reverse().slice(0,200).map(p=>{const period=p.period?.displayValue||p.period?.number||"";const clock=p.clock?.displayValue||p.clock?.value||"";const text=p.text||p.shortText||p.type?.text||p.type?.description||"Play";const score=p.homeScore!=null||p.awayScore!=null?`<em>${esc(p.homeScore??"—")} : ${esc(p.awayScore??"—")}</em>`:"";return `<div class="play"><span>${esc(period)} ${esc(clock)}</span><strong>${esc(text)}</strong>${score}</div>`}).join("")}</div>`}
function renderLeaders(v){
  if(!Array.isArray(v)||!v.length)return"";
  return `<div class="cards-grid">${v.slice(0,12).map(x=>{
    if(!x||typeof x!=="object")return `<div class="data-card">${esc(x)}</div>`;
    const cat=x.name||x.displayName||x.category||x.shortName||"Leader";
    const athletes=x.leaders||x.athletes||x.items||[];
    const arr=Array.isArray(athletes)?athletes.slice(0,5):[];
    const body=arr.length?arr.map(a=>{const ap=a.athlete||a.player||a;const name=ap?.displayName||ap?.fullName||ap?.shortName||"Player";const stats=a.statistics||a.stats||a.value;return `<div class="leader-row"><span>${esc(name)}</span><b>${esc(Array.isArray(stats)?stats.join(" • "):stats??"")}</b></div>`}).join(""):"<span class=\"muted\">Nema detalja</span>";
    return `<div class="data-card"><strong class="card-title">${esc(cat)}</strong>${body}</div>`;
  }).join("")}</div>`
}
function renderStats(v){
  if(!v||typeof v!=="object")return"";
  const teams=Array.isArray(v.teams)?v.teams:[];
  if(teams.length){
    const cards=teams.slice(0,4).map(teamEntry=>{
      const team=teamEntry.team||teamEntry;
      const name=team.displayName||team.name||team.location||"Team";
      const stats=Array.isArray(teamEntry.statistics)?teamEntry.statistics:[];
      const rows=stats.slice(0,20).map(st=>{const label=st.displayName||st.name||st.label;const val=st.displayValue??st.value??"";return label?`<div class="stat-row"><span>${esc(label)}</span><b>${esc(val)}</b></div>`:""}).join("");
      return `<div class="stat-card"><h4>${esc(name)}</h4>${rows||`<div class="muted">${t("no_data")}</div>`}</div>`;
    }).join("");
    if(cards)return `<div class="stats-grid">${cards}</div>`;
  }
  const candidates=[];
  const collect=(obj,prefix="")=>{if(!obj||typeof obj!=="object"||candidates.length>40)return;for(const [k,val] of Object.entries(obj)){if(["id","uid","slug","links","team","athletes","players","competitors"].includes(k))continue;if(typeof val==="string"||typeof val==="number"){if(k.length<50)candidates.push([prefix+k,val]);}else if(Array.isArray(val)){if(val.length&&val.every(x=>typeof x==="object")){for(const x of val.slice(0,5))collect(x,prefix+k+".")}}else if(typeof val==="object")collect(val,prefix+k+".")}};
  collect(v);
  return candidates.length?`<div class="stats-list">${candidates.slice(0,40).map(([k,val])=>`<div class="stat-row"><span>${esc(k.replace(/\./g," • "))}</span><b>${esc(val)}</b></div>`).join("")}</div>`:"";
}
function renderSituation(v){if(!v||typeof v!=="object"||!Object.keys(v).length)return"";const keys=["downDistanceText","possessionText","lastPlay","shortDownDistanceText","isRedZone","possession"].filter(k=>v[k]!=null&&v[k]!=="");return keys.length?`<div class="situation-card">${keys.map(k=>`<div><span>${esc(k.replace(/([A-Z])/g," $1"))}</span><b>${esc(typeof v[k]==="object"?JSON.stringify(v[k]):v[k])}</b></div>`).join("")}</div>`:""}
function renderNews(v){if(!Array.isArray(v)||!v.length)return"";return `<div class="news-list">${v.slice(0,10).map(n=>{const h=n.headline||n.title||n.description||"News";const u=n.links?.web?.href||n.links?.api?.href||n.link;return u?linkButton(u,h):`<div class="news-item">${esc(h)}</div>`}).join("")}</div>`}
async function detail(e){
  const d=$("detail");
  d.innerHTML=`<div class="detail-loading">${t("loading")}</div>`;
  $("modal").classList.remove("hidden");
  document.body.classList.add("modal-open");
  try{
    const r=await fetch("/api/event/"+encodeURIComponent(e.id),{cache:"no-store"});
    const x=r.ok?await r.json():e;
    if(!r.ok)throw new Error(x.error||"HTTP "+r.status);

    const links=x.links||{}, seen=new Set(), buttons=[];
    for(const [k,u] of Object.entries(links)){
      if(u&&!seen.has(u)){seen.add(u);const label=k.replace(/[-_]/g," ").replace(/\b\w/g,c=>c.toUpperCase());buttons.push(linkButton(u,label))}
    }
    if(x.source_url&&!seen.has(x.source_url)){seen.add(x.source_url);buttons.push(linkButton(x.source_url,t("official")))}
    if(String(x.source||"").toLowerCase().includes("espn")){
      const espnUrl="https://www.espn.com/college-sports/";
      if(!seen.has(espnUrl)){seen.add(espnUrl);buttons.push(linkButton(espnUrl,"ESPN College Sports"));}
    }

    const searchLink=(q,label)=>linkButton(`https://www.google.com/search?q=${encodeURIComponent(q)}`,label);
    const teamProfiles=Array.isArray(x.team_profiles)?x.team_profiles:[];
    const headerComp=x.summary?.header?.competitions?.[0]||{};
    const headerTeams=Array.isArray(headerComp.competitors)?headerComp.competitors:[];
    const profiles=teamProfiles.length?teamProfiles:(headerTeams.length?headerTeams.map(c=>({team:c?.team||{},home_away:c?.homeAway,rank:c?.rank,score:c?.score,records:c?.records||[],winner:c?.winner})):[
      {team:{displayName:x.home||"TBD",logo:x.home_logo||""},home_away:"home",score:x.home_score},
      {team:{displayName:x.away||"TBD",logo:x.away_logo||""},home_away:"away",score:x.away_score}
    ]);
    const teamCard=(p,side)=>{
      const tm=p.team&&typeof p.team==="object"?p.team:p;
      const name=tm.displayName||tm.name||tm.location||"TBD";
      const logo=tm.logo||(Array.isArray(tm.logos)&&tm.logos[0]?.href)||"";
      const records=Array.isArray(p.records)?p.records:[];
      const rec=records.map(r=>r?.summary||r?.displayValue||r?.value).filter(Boolean).slice(0,3);
      let providerLinks=[];
      const rawLinks=Array.isArray(tm.links)?tm.links:(Array.isArray(p.links)?p.links:[]);
      for(const l of rawLinks){
        if(!l||typeof l!=="object"||!l.href)continue;
        const rel=Array.isArray(l.rel)?l.rel.join(" ").toLowerCase():String(l.rel||"").toLowerCase();
        const text=l.text||l.shortText||l.label||"Team page";
        providerLinks.push({url:l.href,label:text,rel});
      }
      const teamName=tm.displayName||tm.name||e[side]||"";
      const official=searchLink(`${teamName} official athletics`,t("official_school"));
      const schedule=searchLink(`${teamName} official athletics schedule`,t("official_schedule"));
      const conference=x.conference||x.competition||"NCAA";
      const conf=searchLink(`${conference} NCAA official`,`${conference} ↗`);
      const firstTeamLink=providerLinks.find(l=>/team|official|athletics|school|profile/i.test(l.rel+" "+l.label));
      const schoolUrl=firstTeamLink?.url||`https://www.google.com/search?q=${encodeURIComponent(teamName+" official athletics")}`;
      const logoHtml=logo?`<a class="team-logo-link" href="${esc(schoolUrl)}" target="_blank" rel="noopener noreferrer" title="${esc(t("official_school"))}"><img class="team-logo" src="${esc(logo)}" alt="${esc(teamName)}"></a>`:`<a class="team-logo-link placeholder" href="${esc(schoolUrl)}" target="_blank" rel="noopener noreferrer" title="${esc(t("official_school"))}">NCAA</a>`;
      const providerHtml=providerLinks.slice(0,4).map(l=>linkButton(l.url,l.label)).join("");
      const hubButtons=[
        official,schedule,
        searchLink(`${teamName} official athletics roster`,t("roster")),
        searchLink(`${teamName} official athletics results`,t("results")),
        searchLink(`${teamName} official athletics news`,t("news_school")),
        searchLink(`${teamName} official athletics standings`,t("standings")),
        conf,providerHtml
      ].join("");
      return `<article class="team-profile">
        <div class="team-profile-top">${logoHtml}<div class="team-profile-name"><span class="team-side-label">${side==="home"?"HOME":"AWAY"}</span><h3>${esc(teamName)}</h3><div class="team-abbr">${esc(tm.abbreviation||"")}${tm.location&&tm.location!==teamName?" • "+esc(tm.location):""}</div></div></div>
        <div class="team-facts">
          ${p.rank!=null?`<div><span>Rank</span><b>#${esc(p.rank)}</b></div>`:""}
          ${p.score!=null?`<div><span>Score</span><b>${esc(p.score)}</b></div>`:""}
          ${rec.length?`<div><span>Record</span><b>${esc(rec.join(" • "))}</b></div>`:""}
          ${tm.id?`<div><span>Team ID</span><b>${esc(tm.id)}</b></div>`:""}
        </div>
        <div class="team-actions">${hubButtons}</div>
      </article>`;
    };
    const homeProfile=profiles.find(p=>p.home_away==="home")||profiles[0];
    const awayProfile=profiles.find(p=>p.home_away==="away")||profiles.find(p=>p!==homeProfile)||profiles[1];
    const teamSection=profiles.length?section(t("teams"),`<div class="team-profile-grid">${homeProfile?teamCard(homeProfile,"home"):""}${awayProfile?teamCard(awayProfile,"away"):""}</div>`):"";

    const conferenceName=x.conference||x.competition||"NCAA";
    const conferenceSection=section(t("competition"),`<div class="conference-hub"><div><strong>${esc(conferenceName)}</strong><span>${x.conference?esc(x.competition||"NCAA"):t("official")}</span></div>${searchLink(`${conferenceName} NCAA conference official`,`${conferenceName} • official ↗`)}${searchLink(`${conferenceName} NCAA standings`,`${conferenceName} • standings ↗`)}${searchLink(`${conferenceName} NCAA teams`,`${conferenceName} • teams ↗`)}</div>`);

    const officialSearch=`<div class="official-search"><div class="official-note">${t("legal_note")}</div><div class="official-buttons">${officialSearchButton(x.home,"school")}${officialSearchButton(x.home,"schedule")}${officialSearchButton(x.away,"school")}${officialSearchButton(x.away,"schedule")}</div></div>`;
    const hasScore=(x.home_score??"")!==""||(x.away_score??"")!=="";
    const score=hasScore?`<div class="scoreline"><div><span class="score-team">${esc(x.home||"TBD")}</span><b>${esc(x.home_score??"—")}</b></div><span class="score-sep">:</span><div><b>${esc(x.away_score??"—")}</b><span class="score-team">${esc(x.away||"TBD")}</span></div></div>`:"";
    const bcast=(x.broadcasts||[]).length?section(t("broadcast"),`<div class="pill-list">${x.broadcasts.map(esc).map(v=>`<span class="pill">${v}</span>`).join("")}</div>`):"";
    const notes=(x.notes||[]).length?section(t("notes"),x.notes.map(n=>`<p>${esc(n)}</p>`).join("")):"";
    const s=x.summary||{};
    const live=x.summary_available
      ?section(t("playbyplay"),renderPlays(s.plays))
      +section(t("leaders"),renderLeaders(s.leaders))
      +section(t("stats"),renderStats(s.boxscore))
      +section(t("odds"),renderStats({items:s.odds}))
      +section(t("winprob"),renderStats({items:s.winprobability}))
      +section(t("news"),renderNews(s.news))
      +section(t("live"),renderSituation(s.situation))
      :"";
    const raw=x.summary_available?`<details class="raw"><summary>${t("raw")}</summary><pre>${esc(JSON.stringify(s.raw||s,null,2))}</pre></details>`:"";
    const available=[
      ["Score / status",(x.status||x.home_score!=null||x.away_score!=null)],
      ["Venue",!!x.venue],["Competition",!!x.competition],["Conference",!!x.conference],
      ["Team profiles",teamProfiles.length>=2],["Team logos",teamProfiles.some(p=>p.logo||p.logos?.length)],
      ["Team links",teamProfiles.some(p=>Array.isArray(p.links)&&p.links.length)],
      ["Broadcast",Array.isArray(x.broadcasts)&&x.broadcasts.length],
      ["Play-by-Play",Array.isArray(s.plays)&&s.plays.length],
      ["Statistics",!!(s.boxscore&&Object.keys(s.boxscore).length)],
      ["Leaders",Array.isArray(s.leaders)&&s.leaders.length],
      ["Odds",Array.isArray(s.odds)&&s.odds.length],
      ["Win probability",Array.isArray(s.winprobability)&&s.winprobability.length],
      ["News",Array.isArray(s.news)&&s.news.length],
      ["Provider links",Object.keys(x.links||{}).length]
    ];
    const availabilitySection=section(t("data_available"),`<div class="availability-grid">${available.map(([k,v])=>`<div class="${v?"available":"unavailable"}"><span>${v?"✓":"—"}</span><b>${esc(k)}</b><small>${v?t("available"):t("no_data")}</small></div>`).join("")}</div>`);
    const local=formatZone(x.start_utc,timezone,true);
    const utc=x.start_utc||"TBD";

    d.innerHTML=`<div class="gc-head">
      <div><div class="eyebrow">${esc(t("details"))}</div><h2>${esc(x.home||"TBD")} <span>vs</span> ${esc(x.away||"TBD")}</h2><div class="gc-status">${esc(x.status||t("scheduled"))}</div></div>${score}
    </div>
    ${teamSection}
    <div class="gc-grid"><div class="gc-main">
      <div class="info-grid">
        <div><label>${t("sport")}</label><strong>${esc(SPORTS[x.sport]||x.sport||"TBD")}</strong></div>
        <div><label>${t("competition")}</label><strong>${esc(x.competition||"NCAA")}${x.conference?" / "+esc(x.conference):""}</strong></div>
        <div><label>${esc(t("local_time"))} · ${esc(zoneLabel(timezone))}</label><strong>${esc(local)}</strong></div>
        <div><label>${t("utc_time")}</label><strong>${esc(utc)}</strong></div>
        <div><label>${t("venue")}</label><strong>${esc(x.venue||"TBD")}</strong></div>
        <div><label>${t("confidence")}</label><strong>${Math.round((x.confidence||0)*100)}%</strong></div>
      </div>
      ${conferenceSection}
      ${section(t("links"),buttons.length?buttons.join("")+officialSearch:officialSearch)}
      ${bcast}${notes}${availabilitySection}${live}${raw}
    </div>
    <aside class="gc-side">
      ${section(t("teams"),`<div class="team-side"><strong>${esc(x.home||"TBD")}</strong><span>vs</span><strong>${esc(x.away||"TBD")}</strong></div>`)}
      ${x.home_rank||x.away_rank?section(t("rankings"),`<div class="rankings"><span>${esc(x.home_rank||"—")}</span><b>:</b><span>${esc(x.away_rank||"—")}</span></div>`):""}
      <div class="side-note">${t("refresh")}: ${new Date().toISOString().replace("T"," ").slice(0,19)} UTC</div>
    </aside></div>`;
  }catch(err){
    d.innerHTML=`<h2>${esc(e.home||"TBD")} vs ${esc(e.away||"TBD")}</h2><div class="empty">${esc(err.message||"Unable to load event details.")}</div>`;
  }
}
async function loadHealth(){
  try{
    const r=await fetch('/api/health',{cache:'no-store'}); const h=await r.json(); const el=$("engineStatusText"); const box=$("status");
    if(h.refresh?.status==='refreshing' || h.refresh?.status==='starting') {box.className='data-engine-status refreshing';el.textContent=`Data engine ${h.refresh.status} • ${h.events||0} events cached • refreshing live sources…`;}
    else if(h.refresh?.status==='error'){box.className='data-engine-status error';el.textContent=`Data engine error • ${h.events||0} cached events • ${h.refresh.error||'check Sources'}`;}
    else {box.className='data-engine-status';el.textContent=`Data engine online • ${h.events||0} verified events cached • last refresh ${h.refresh?.finished_at||'—'}`;}
  }catch(e){const box=$("status");box.className='data-engine-status error';$("engineStatusText").textContent='Data engine connection unavailable — retrying automatically';}
}
async function load(){
  loadHealth();
  let liveOk=false;
  try{
    const response=await fetch("/api/events",{cache:"no-store",headers:{Accept:"application/json"}});
    if(!response.ok)throw new Error("HTTP "+response.status);
    const data=await response.json();
    if(!Array.isArray(data))throw new Error("Invalid API response");
    events=data.map(e=>({...e,sport:canonicalSport(e.sport)}));
    liveOk=true;
  }catch(error){
    console.warn("NCAA live API:",error);
    if(!events.length){
      try{
        const r=await fetch("/events_snapshot.json",{cache:"no-store"});
        if(r.ok){const data=await r.json(); if(Array.isArray(data)) events=data.map(e=>({...e,sport:canonicalSport(e.sport)}));}
      }catch(snapshotError){console.warn("snapshot",snapshotError)}
    }
  }
  if(!directory?.sports || !Object.keys(directory.sports).length) await loadDirectory(); else renderSchoolDirectory();
  render();
  const box=$("status"),el=$("engineStatusText");
  if(events.length && !liveOk){box.className="data-engine-status refreshing";el.textContent=`Presentation data online • ${events.length} verified events • live service reconnecting…`;}
  else if(events.length && liveOk){box.className="data-engine-status";el.textContent=`Data engine online • ${events.length} verified events loaded`;}
  if(!liveOk) setTimeout(load,10000);
}
function clock(){const d=new Date();const utc=d.toISOString().replace("T"," ").slice(0,19)+" UTC";$("clock").innerHTML=`<span class="clock-main">${esc(utc)}</span><span class="clock-utc">Primary time • UTC</span>`}
setDirection();setup();
setTimeout(()=>{const s=document.getElementById("brandSplash");if(s){s.classList.add("splash-hide");setTimeout(()=>s.remove(),500)}},1400);
document.querySelector('#ranges button[data-r="today"]').classList.add("active");load();clock();setInterval(clock,1000);setInterval(load,30000);setInterval(loadHealth,10000);
